#include <windows.h>
#include <stdio.h>
static int ink_w(HDC dc,int W,int H){int mn=W,mx=-1;for(int y=0;y<H;y++)for(int x=0;x<W;x++)if(GetPixel(dc,x,y)!=RGB(0,0,0)){if(x<mn)mn=x;if(x>mx)mx=x;}return mx>=mn?mx-mn+1:0;}
static int measure(int hpx,int lfWidth,const char*out){const int W=1600,H=300;HDC s=GetDC(NULL);HDC dc=CreateCompatibleDC(s);BITMAPINFO bi;memset(&bi,0,sizeof bi);bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=W;bi.bmiHeader.biHeight=-H;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=24;bi.bmiHeader.biCompression=BI_RGB;void*bits=NULL;HBITMAP bm=CreateDIBSection(s,&bi,DIB_RGB_COLORS,&bits,NULL,0);HBITMAP ob=(HBITMAP)SelectObject(dc,bm);RECT r={0,0,W,H};HBRUSH bg=CreateSolidBrush(RGB(0,0,0));FillRect(dc,&r,bg);DeleteObject(bg);HFONT f=CreateFontW(-hpx,lfWidth,0,0,FW_NORMAL,0,0,0,DEFAULT_CHARSET,OUT_TT_ONLY_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH|FF_DONTCARE,L"Arial");HFONT of=(HFONT)SelectObject(dc,f);SetBkMode(dc,TRANSPARENT);SetTextColor(dc,RGB(255,255,255));SetTextAlign(dc,TA_LEFT|TA_BASELINE);TextOutW(dc,20,H-60,L"ABCDEFGHIJ",10);int w=ink_w(dc,W,H);if(out){unsigned char*px=malloc((size_t)W*H*3);BITMAPINFO gb;memset(&gb,0,sizeof gb);gb.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);gb.bmiHeader.biWidth=W;gb.bmiHeader.biHeight=-H;gb.bmiHeader.biPlanes=1;gb.bmiHeader.biBitCount=24;gb.bmiHeader.biCompression=BI_RGB;GetDIBits(dc,bm,0,H,px,&gb,DIB_RGB_COLORS);FILE*fp=fopen(out,"wb");if(fp){BITMAPFILEHEADER fh;memset(&fh,0,sizeof fh);fh.bfType=0x4D42;fh.bfOffBits=sizeof(fh)+sizeof(BITMAPINFOHEADER);fh.bfSize=fh.bfOffBits+W*H*3;fwrite(&fh,1,sizeof fh,fp);fwrite(&gb.bmiHeader,1,sizeof(BITMAPINFOHEADER),fp);fwrite(px,1,(size_t)W*H*3,fp);fclose(fp);}free(px);}SelectObject(dc,of);DeleteObject(f);SelectObject(dc,ob);DeleteObject(bm);DeleteDC(dc);ReleaseDC(NULL,s);return w;}
int main(void){int b30=measure(30,0,NULL),b60=measure(60,0,NULL);for(int k=0;k<=4;k++){double wf=0.6+0.1*k;int lw30=(int)(30*0.448*wf+0.5);int lw60=(int)(60*0.448*wf+0.5);int a=measure(30,-lw30,NULL),b=measure(60,-lw60,NULL);printf("wf=%.1f h30 lw=-%d ratio=%.3f | h60 lw=-%d ratio=%.3f\n",wf,lw30,(double)a/b30,lw60,(double)b/b60);}measure(60,0,"C:\\tmp\\lw_base.bmp");measure(60,-(int)(60*0.448*0.7),NULL);measure(60,-19,"C:\\tmp\\lw07.bmp");return 0;}
